Even NA has a type



class(NA)



[1] "logical"




NA takes the type of the vector it sits in:

class(c(1.5, NA))
class(c("a", NA))



[1] "numeric"
[1] "character"





There’s an NA for every type (NA_real_, NA_character_, …)


Usually you don’t need to be explicit.

Extracting a column


$ and [[ return a column as a vector

class(counties$income)
class(counties[["income"]])



[1] "numeric"
[1] "numeric"



Both approaches return a vector


[ instead returns a one-column tibble


class(counties["income"])



[1] "tbl_df"     "tbl"        "data.frame"

select(): ranges and exclusions


We can also select with ranges …

counties |&gt;
    select(state:income) |&gt;
    names()



[1] "state"  "county" "income"



… and with exclusions:

counties |&gt;
    select(-c(income_moe, rent_moe)) |&gt;
    names()



[1] "GEOID"  "state"  "county" "income" "rent"

Selection helpers


We can select based on names using starts_with(), ends_with(), and contains()

counties |&gt;
    select(starts_with("rent")) |&gt;
    names()



[1] "rent"     "rent_moe"



Or with a helper function inside where():

counties |&gt;
    select(where(is.numeric)) |&gt;
    names()



[1] "income"     "income_moe" "rent"       "rent_moe"

relocate()


Move columns to the front:

counties |&gt;
    relocate(income, rent) |&gt;
    names()



[1] "income"     "rent"       "GEOID"      "state"      "county"    
[6] "income_moe" "rent_moe"  



Or to a specific location:

counties |&gt;
    relocate(county, .after = state) |&gt;
    names()



[1] "GEOID"      "state"      "county"     "income"     "income_moe"
[6] "rent"       "rent_moe"

A solution



counties |&gt;
    filter(state %in% c("New York", "Texas")) |&gt;
    mutate(income_thousands = income / 1000) |&gt;
    select(state, county, income, income_thousands) |&gt;
    arrange(desc(income))



# A tibble: 316 × 4
  state    county         income income_thousands
  &lt;chr&gt;    &lt;chr&gt;           &lt;dbl&gt;            &lt;dbl&gt;
1 New York Nassau County  143408             143.
2 New York Suffolk County 128329             128.
3 New York Putnam County  127405             127.
# ℹ 313 more rows

Grouped mutation


mutate() will respect groups for vectorized operations

counties |&gt;
    group_by(state) |&gt;
    mutate(
        income_difference = income - mean(income, na.rm = TRUE)
    ) |&gt;
    select(state, county, income, income_difference) |&gt;
    ungroup()



# A tibble: 3,144 × 4
  state   county         income income_difference
  &lt;chr&gt;   &lt;chr&gt;           &lt;dbl&gt;             &lt;dbl&gt;
1 Alabama Autauga County  69841            15645.
2 Alabama Baldwin County  75019            20823.
3 Alabama Barbour County  44290            -9906.
# ℹ 3,141 more rows

Multiple summaries: across()



counties |&gt;
    summarize(
        across(
            c(income, rent),
            list(
                mean = \(x) mean(x, na.rm = TRUE),
                sd = \(x) sd(x, na.rm = TRUE)
            )
        )
    )



# A tibble: 1 × 4
  income_mean income_sd rent_mean rent_sd
        &lt;dbl&gt;     &lt;dbl&gt;     &lt;dbl&gt;   &lt;dbl&gt;
1      66073.    17387.      938.    302.



across() applies the same functions to several columns

A solution



sol &lt;- counties |&gt;
    filter(!is.na(income)) |&gt;
    mutate(
        income_level = if_else(
            income &gt;= median(income),
            "at or above median",
            "below median"
        )
    ) |&gt;
    group_by(income_level) |&gt;
    summarize(
        n = n(),
        across(c(income, rent), \(x) mean(x, na.rm = TRUE)),
        .groups = "drop"
    ) |&gt;
    arrange(desc(income))

Check the key


A key should identify the intended unit of observation

attitudes |&gt;
    count(id) |&gt;
    filter(n &gt; 1L)



# A tibble: 0 × 2
# ℹ 2 variables: id &lt;int&gt;, n &lt;int&gt;



An empty result means no duplicate keys were found

Mapping over data frames


Create a list of tibbles with group_split():

counties_by_region &lt;- counties_joined |&gt;
    filter(!is.na(region)) |&gt;
    group_by(region) |&gt;
    group_split()





map_dbl() then returns one value per tibble:


map_dbl(
    counties_by_region,
    \(x) mean(x$income, na.rm = TRUE)
)



[1] 67678.39 78195.17 60859.68 72626.80

Step 1: label population


counties_labeled &lt;- counties_joined |&gt;
    mutate(
        pop_level = # ...
    )

Use if_else() or case_when()

One possible solution



result &lt;- counties_joined |&gt;
    filter(!is.na(pop), !is.na(region)) |&gt;
    mutate(
        pop_level = if_else(
            pop &gt;= median(pop),
            "at or above median",
            "below median"
        )
    ) |&gt;
    group_by(region, pop_level) |&gt;
    summarize(
        n = n(),
        mean_income = mean(income, na.rm = TRUE),
        .groups = "drop"
    ) |&gt;
    arrange(desc(mean_income))

Apply a function to each group



region_summary &lt;- function(data) {
    data |&gt;
        summarize(
            n = n(),
            mean_income = mean(income, na.rm = TRUE),
            median_rent = median(rent, na.rm = TRUE)
        )
}





Apply region_summary() to each region with map()

One possible solution



by_region &lt;- counties_joined |&gt;
    filter(!is.na(region)) |&gt;
    group_by(region) |&gt;
    group_split()

by_region |&gt;
    map(region_summary) |&gt;
    list_rbind()



# A tibble: 4 × 3
      n mean_income median_rent
  &lt;int&gt;       &lt;dbl&gt;       &lt;dbl&gt;
1  1055      67678.         804
2   209      78195.        1056
3  1422      60860.         845
# ℹ 1 more row

Writing code that produces readable diffs


county &lt;- county |&gt; filter(year != 2020) |&gt; mutate(income_k = income / 1000) |&gt; group_by(region) |&gt; summarise(m = mean(income_k, na.rm = TRUE))

Change one thing here and the diff says this line changed. Useless.



county_summary &lt;- county |&gt;
    filter(year != 2020) |&gt;
    mutate(income_k = income / 1000) |&gt;
    group_by(region) |&gt;
    summarise(m = mean(income_k, na.rm = TRUE))



Now the diff points at the step/line(s) you changed.

Sampling distributions

sizes &lt;- c(2, 5, 30, 100, 1000)

samp &lt;- map_dfr(sizes, function(n) {
    tibble(
        n = n,
        xbar = replicate(10000, mean(sample(pop_all, size = n, replace = TRUE)))
    )
})

samp |&gt;
    mutate(n = factor(n, levels = sizes, labels = paste("n =", sizes))) |&gt;
    ggplot(aes(x = xbar)) +
    geom_histogram(bins = 50) +
    facet_wrap(~n, scales = "free", nrow = 1) +
    scale_x_continuous(
        labels = scales::label_number(scale_cut = scales::cut_short_scale())
    ) +
    labs(x = "Sample mean of county population", y = "Count") +
    theme_minimal(base_size = 13) +
    theme(axis.text.x = element_text(angle = 45, hjust = 1))








The x-axes are free, so read the axis labels rather than the apparent widths. At n = 2 the distribution still looks like the population — a spike on the left with a tail. By n = 100 it is nearly symmetric, and at n = 1000 it is a clean bell centred on the population mean.

Composition: stacked bars


Split each region’s counties into high- and low-population halves:

counties &lt;- counties |&gt;
    mutate(pop_level = if_else(
        pop &gt;= median(counties$pop, na.rm = T),
        "high pop", "low_pop"
    ))

counties |&gt;
    filter(!is.na(pop_level)) |&gt;
    ## piping in this data; now different operator!
    ggplot(aes(x = region, fill = pop_level)) +
    geom_bar()

Counts vs. shares: position


position = "fill" rescales every bar to 1

counties |&gt;
    filter(!is.na(pop_level)) |&gt;
    ggplot(aes(x = region, fill = pop_level)) +
    geom_bar(position = "fill")

Side by side: position = "dodge"



counties |&gt;
    filter(!is.na(pop_level)) |&gt;
    ggplot(aes(x = region, fill = pop_level)) +
    geom_bar(position = "dodge")











Three versions of the same bars — stacked, filled, dodged. Which question does each answer best?

Counties to states




shapes |&gt;
    group_by(state) |&gt;
    summarise(geometry = st_union(geometry)) |&gt;
    plot(main = NULL)
